static size_t checks=0,cases=0,values=0,independent=0;
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
static void req(bool b,const char*s){++checks;if(!b){fprintf(stderr,"FAIL %s\n",s);exit(3);}}
static void shape(ggml_tensor&t,ggml_type type,std::array<int64_t,4>ne,int pad=0){memset(&t,0,sizeof t);t.type=type;for(int i=0;i<4;i++)t.ne[i]=ne[i];t.nb[0]=4;t.nb[1]=(ne[0]+pad)*4;t.nb[2]=t.nb[1]*ne[1];t.nb[3]=t.nb[2]*ne[2];}
static size_t span(const ggml_tensor&t){size_t n=4;for(int i=0;i<4;i++)n+=(t.ne[i]-1)*t.nb[i];return n;}
struct Buf{static constexpr size_t guard=64;unsigned char*p;size_t n;explicit Buf(size_t bytes):n(bytes+2*guard){ck(cudaMalloc(&p,n));ck(cudaMemset(p,0xA5,n));ck(cudaStreamSynchronize(nullptr));}~Buf(){ck(cudaFree(p));}void*data(){return p+guard;}};
static std::vector<unsigned char>get(Buf&b){std::vector<unsigned char>r(b.n);ck(cudaMemcpy(r.data(),b.p,b.n,cudaMemcpyDeviceToHost));return r;}
static float sample(int64_t col,int64_t row,int pattern){switch(pattern){case 1:return float((col+row)%7-3);case 2:return 9.0f;case 3:return NAN;case 4:return-FLT_MAX;case 5:return col%3==0?NAN:float(col%11);case 6:return col%13==0?INFINITY:(col%7==0?-INFINITY:-1.0f);case 7:return col%2==0?-0.0f:0.0f;default:return float(((col+row*103)*31337)%50003-25001)/4096.0f;}}
static std::vector<unsigned char>fill(Buf&b,const ggml_tensor&t,int pattern){std::vector<unsigned char>h(b.n,0xA5);int64_t row=0;for(int64_t i3=0;i3<t.ne[3];i3++)for(int64_t i2=0;i2<t.ne[2];i2++)for(int64_t i1=0;i1<t.ne[1];i1++,row++)for(int64_t i0=0;i0<t.ne[0];i0++){float v=sample(i0,row,pattern);size_t off=Buf::guard+i0*t.nb[0]+i1*t.nb[1]+i2*t.nb[2]+i3*t.nb[3];memcpy(h.data()+off,&v,4);}ck(cudaMemcpy(b.p,h.data(),h.size(),cudaMemcpyHostToDevice));ck(cudaStreamSynchronize(nullptr));return h;}
static float read(const std::vector<unsigned char>&h,const ggml_tensor&t,int64_t row,int64_t col){int64_t i1=row%t.ne[1],i2=(row/t.ne[1])%t.ne[2],i3=row/(t.ne[1]*t.ne[2]);float v;memcpy(&v,h.data()+Buf::guard+col*t.nb[0]+i1*t.nb[1]+i2*t.nb[2]+i3*t.nb[3],4);return v;}
struct Pair{float v;int32_t c;};
static void warp(Pair*p){for(int off=16;off;off>>=1){Pair old[32];memcpy(old,p,sizeof old);for(int l=0;l<32;l++)if(old[l^off].v>old[l].v)p[l]=old[l^off];}}
static int32_t argref(const std::vector<unsigned char>&h,const ggml_tensor&t,int64_t row){int bs=int(std::min<int64_t>(1024,(t.ne[0]+31)/32*32));std::vector<Pair>p(bs,Pair{-FLT_MAX,-1});for(int tid=0;tid<bs;tid++)for(int64_t col=tid;col<t.ne[0];col+=bs){float v=read(h,t,row,col);if(v>p[tid].v)p[tid]={v,(int32_t)col};}for(int w=0;w<bs/32;w++)warp(p.data()+w*32);if(bs>32){Pair q[32];memcpy(q,p.data(),sizeof q);for(int w=0;w<bs/32;w++)q[w]=p[w*32];warp(q);return q[0].c;}return p[0].c;}
static float sumref(const std::vector<unsigned char>&h,const ggml_tensor&t,int64_t row,int bs){std::vector<float>p(bs);for(int tid=0;tid<bs;tid++){float acc[8]={};int64_t i=tid;while(i<t.ne[0]){float tmp[8];for(int j=0;j<8;j++,i+=bs)tmp[j]=i<t.ne[0]?read(h,t,row,i):0.0f;for(int j=0;j<8;j++)acc[j]+=tmp[j];}for(int j=0;j<8;j++)p[tid]+=acc[j];}auto fold=[](float*a){for(int off=16;off;off>>=1){float old[32];memcpy(old,a,sizeof old);for(int l=0;l<32;l++)a[l]+=old[l^off];}};for(int w=0;w<bs/32;w++)fold(p.data()+w*32);if(bs>32){float q[32]={};for(int w=0;w<bs/32;w++)q[w]=p[w*32];fold(q);return q[0];}return p[0];}
static void invoke(int mode,bool native,ggml_backend_cuda_context&ctx,ggml_tensor&x,ggml_tensor&d,int64_t cols,int64_t rows,bool sync=true){switch(mode){case 0:if(native)fg169_native_ggml_cuda_op_sum_rows(ctx,&d);else ggml_cuda_op_sum_rows(ctx,&d);break;case 1:if(native)fg169_native_ggml_cuda_op_mean(ctx,&d);else ggml_cuda_op_mean(ctx,&d);break;case 2:if(native)fg169_native_ggml_cuda_argmax(ctx,&d);else ggml_cuda_argmax(ctx,&d);break;case 3:if(native)fg169_native_sum_rows_f32_cuda((const float*)x.data,(float*)d.data,cols,rows,ctx.stream());else sum_rows_f32_cuda((const float*)x.data,(float*)d.data,cols,rows,ctx.stream());break;case 4:if(native)fg169_native_ggml_cuda_op_sum(ctx,&d);else ggml_cuda_op_sum(ctx,&d);break;case 5:if(native)fg169_native_sum_f32_cuda(ctx.pool(),(const float*)x.data,(float*)d.data,cols*rows,ctx.stream());else sum_f32_cuda(ctx.pool(),(const float*)x.data,(float*)d.data,cols*rows,ctx.stream());break;}if(sync)ck(cudaStreamSynchronize(ctx.stream()));}
static void test(int mode,int64_t cols,int64_t rows,int pad,int pattern,bool permute,ggml_backend_cuda_context&ctx,int layout=0){ggml_tensor x,d;shape(x,GGML_TYPE_F32,{cols,rows,1,1},pad);if(layout){req(rows==12,"4D row count");shape(x,GGML_TYPE_F32,{cols,3,2,2},pad);x.nb[2]+=20;x.nb[3]=x.nb[2]*2+36;if(layout==2)x.nb[2]=0;}if(permute){req(mode==4,"permutation only global sum");x.nb[0]=rows*4;x.nb[1]=4;x.nb[2]=cols*rows*4;x.nb[3]=x.nb[2];}int64_t outrows=mode>=4?1:rows;shape(d,mode==2?GGML_TYPE_I32:GGML_TYPE_F32,{outrows,1,1,1});Buf xb(span(x)),gb(outrows*4),nb(outrows*4);auto original=fill(xb,x,pattern);x.data=xb.data();d.src[0]=&x;d.data=gb.data();invoke(mode,false,ctx,x,d,cols,rows);auto got=get(gb);d.data=nb.data();invoke(mode,true,ctx,x,d,cols,rows);auto expected=get(nb);if(got!=expected){for(size_t i=0;i<got.size();i++)if(got[i]!=expected[i]){fprintf(stderr,"MISMATCH mode=%d cols=%lld rows=%lld pad=%d pattern=%d permute=%d byte=%zu got=%02x want=%02x\n",mode,(long long)cols,(long long)rows,pad,pattern,permute,i,got[i],expected[i]);break;}}req(got==expected,"native bit-exact output including guards");req(get(xb)==original,"all input logical and padding bytes unchanged");for(size_t i=0;i<Buf::guard;i++)req(got[i]==0xA5&&got[got.size()-1-i]==0xA5,"output guards intact");int bs=rows/ggml_cuda_info().devices[0].nsm<2?512:(cols<1024?32:128);for(int64_t row=0;row<outrows;row++){if(mode==2){int32_t v;memcpy(&v,got.data()+Buf::guard+row*4,4);req(v==argref(original,x,row),"independent native-order tie/NaN/index oracle");independent++;}else if((mode==0||mode==3)||(mode==1&&(cols&(cols-1))==0&&cols<=32768)){float ref=sumref(original,x,row,bs);if(mode==1)ref/=float(cols);float actual;memcpy(&actual,got.data()+Buf::guard+row*4,4);req(memcmp(&actual,&ref,4)==0,"independent row-order float reduction");independent++;}else if(mode>=4&&pattern==1){float ref=0;for(int64_t r=0;r<rows;r++)for(int64_t c=0;c<cols;c++)ref+=read(original,x,r,c);float actual;memcpy(&actual,got.data()+Buf::guard,4);req(memcmp(&actual,&ref,4)==0,"independent exact integer-valued global sum");independent++;}}req(fg169_cuda_live_temp()==0,"Goose-owned external CUB temp released");cases++;values+=cols*rows;}
static size_t graph_cases=0;
static void graph_test(int mode,int64_t cols,int64_t rows,ggml_backend_cuda_context&ctx){ggml_tensor x,d;shape(x,GGML_TYPE_F32,{cols,rows,1,1});const int64_t outputs=mode>=4?1:rows;shape(d,mode==2?GGML_TYPE_I32:GGML_TYPE_F32,{outputs,1,1,1});Buf xb(span(x)),gb(outputs*4),nb(outputs*4);auto original=fill(xb,x,0);x.data=xb.data();d.src[0]=&x;for(int native=0;native<2;native++){d.data=native?nb.data():gb.data();cudaGraph_t graph;cudaGraphExec_t exec;ck(cudaStreamBeginCapture(ctx.stream(),cudaStreamCaptureModeGlobal));invoke(mode,native,ctx,x,d,cols,rows,false);ck(cudaStreamEndCapture(ctx.stream(),&graph));ck(cudaGraphInstantiate(&exec,graph,nullptr,nullptr,0));ck(cudaGraphLaunch(exec,ctx.stream()));ck(cudaStreamSynchronize(ctx.stream()));ck(cudaGraphExecDestroy(exec));ck(cudaGraphDestroy(graph));}req(get(gb)==get(nb),"native-compatible CUDA graph capture/replay");req(get(xb)==original,"graph input unchanged");req(fg169_cuda_live_temp()==0,"graph CUB temp released");graph_cases++;}
int main(){ck(cudaSetDevice(0));ggml_backend_cuda_context ctx(0);int nsm=ggml_cuda_info().devices[0].nsm;for(int mode:{0,1,3})for(int64_t n:{1,31,32,33,127,128,511,512,1023,1024,4097,16384})for(int64_t rows:{1,3,2*nsm})for(int pad:{0,7}){if(mode==3&&pad)continue;test(mode,n,rows,pad,0,false,ctx);}for(int64_t n:{32768,32769,65536,65537,131073})test(1,n,1,0,0,false,ctx);for(int64_t n:{1,2,3,31,32,33,63,64,127,1023,1024,1025,4097,65537})for(int pattern=0;pattern<8;pattern++)test(2,n,3,0,pattern,false,ctx);for(int mode:{4,5})for(int64_t n:{1,31,1024,65537,131073})for(int pattern:{0,1})test(mode,n,3,0,pattern,false,ctx);test(4,7,3,0,1,true,ctx);for(int mode:{0,1})for(int layout:{1,2})for(int64_t n:{33,1024})test(mode,n,12,7,0,false,ctx,layout);for(int mode=0;mode<6;mode++)graph_test(mode,1024,3,ctx);graph_test(1,32769,1,ctx);graph_test(1,65537,1,ctx);uint64_t bits=0;req(fg169_cuda_device_read(&bits)==0,"device witness read");bool rollback=getenv("GGML_GOOSE_CUDA_REDUCTIONS")&&strcmp(getenv("GGML_GOOSE_CUDA_REDUCTIONS"),"0")==0;req(rollback?fg169_cuda_host_seen()==0:fg169_cuda_host_seen()==63,"all6host routes or rollback silent");if(rollback)req(bits==0&&fg169_cuda_cub_seen()==0,"rollback no Goose/CUB orchestration witness");else{req((bits&15)==15,"row sum/mean/argmax/raw-row GPU witnesses");
#ifdef GGML_CUDA_USE_CUB
req((fg169_cuda_cub_seen()&50)==50&&(bits&256),"external CUB sum/rawsum/longmean and Goose postdivision");
#endif
}printf("PASS cases=%zu values=%zu checks=%zu independent=%zu graph_cases=%zu host=0x%llx device=0x%llx cub=0x%llx live_temp=%llu rollback=%d\n",cases,values,checks,independent,graph_cases,(unsigned long long)fg169_cuda_host_seen(),(unsigned long long)bits,(unsigned long long)fg169_cuda_cub_seen(),(unsigned long long)fg169_cuda_live_temp(),rollback);}
